-- Operations analytics wiki section (top-level sibling of "Data modeling").
-- Idempotent: pages upsert by slug; parent wiring and wikilinks are join-based and
-- safe to re-run. Cross-section wikilinks resolve only once the target pages exist,
-- so re-run all five domain seeds after the first pass to wire cross-links.
-- Mirrors what was seeded to the live DB via the Supabase MCP (2026-06).

insert into pages (title, slug, kind, content, visibility) values ('Operations analytics', 'ops-analytics', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Operations analytics is the analytics that keeps the business running efficiently: cost, capacity, throughput, and the cost-to-serve. It's the least tidy of the domain sections, and it's worth being honest about why up front."}]},{"type":"paragraph","content":[{"type":"text","text":"Unlike product or marketing analytics, operations analytics is not one codified discipline. It's an umbrella over several functions that each have their own canon: BizOps (cross-functional decision support), RevOps (the go-to-market operating system), and FinOps (cloud financial management, the most rigorous of the three). The distinguishing lens across all of them is efficiency and cost, not revenue or behavior."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Theory"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The frame — ","marks":[{"type":"bold"}]},{"type":"text","text":"what ops analytics actually is, and the SLA, throughput, and efficiency metrics that run it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cost — ","marks":[{"type":"bold"}]},{"type":"text","text":"SaaS COGS and gross margin, FinOps and cloud cost, cost attribution."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The idea — ","marks":[{"type":"bold"}]},{"type":"text","text":"cost as a data product, modeling the bill with the same rigor as any other data."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Practice"}]},{"type":"paragraph","content":[{"type":"text","text":"Cost attribution in dbt, FOCUS and billing exports, capacity forecasting, operational metrics in the semantic layer, and the hub-and-spoke org debate."}]},{"type":"paragraph","content":[{"type":"text","text":"The most taro-shaped idea in this whole section: seeing the cloud bill doesn't change anyone's behavior, but owning a modeled, attributed slice of it does. Cost is a data product."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"What ops analytics is"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Operations analytics practice"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Ops voices and canon"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('What ops analytics is', 'what-ops-analytics-is', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Be honest with the reader: operations analytics is a loose umbrella, not a tight discipline. It surfaces under three named functions that do have canon, and it helps to keep them straight."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"BizOps — ","marks":[{"type":"bold"}]},{"type":"text","text":"business operations, the cross-functional decision-support and strategy-execution glue. Real but diffuse, with no unifying book."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"RevOps — ","marks":[{"type":"bold"}]},{"type":"text","text":"revenue operations, the go-to-market operating system across sales, marketing, and CS ops. Covered on the sales side at "}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The cleanest way to draw the line against the other domains is by the question each asks. Product analytics asks how users behave. Marketing asks where demand comes from. Sales asks will we hit the number. Finance asks what the P&L is. Operations analytics asks: are we running efficiently, and at what cost-to-serve. The grain and entities follow from that: cost lines, usage events, headcount, vendors, work items."}]},{"type":"paragraph","content":[{"type":"text","text":"FinOps is the one rigorously standardized slice, with a formal framework, a certification, and an annual conference. The rest is real work done under looser names. Naming that ambiguity is more useful than pretending it's a clean field. See "},{"type":"wikilink","attrs":{"title":"RevOps as a function"}},{"type":"text","text":" for the go-to-market half."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"SLAs, SLOs and operational KPIs"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"RevOps as a function"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"FinOps and cloud cost"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('SLAs, SLOs and operational KPIs', 'slas-slos-operational-kpis', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The service-level vocabulary gets used loosely, and the distinctions matter when you model them. The hierarchy:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SLI — ","marks":[{"type":"bold"}]},{"type":"text","text":"service level indicator, a measured value: request latency, the share of successful requests, uptime."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SLO — ","marks":[{"type":"bold"}]},{"type":"text","text":"service level objective, the internal target for an SLI over a window, like 99.9% monthly availability."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SLA — ","marks":[{"type":"bold"}]},{"type":"text","text":"service level agreement, the contractual promise to customers, with penalties, usually looser than the internal SLO."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Other operational KPIs cluster around the same idea: availability, mean time to recovery, error rate, ticket backlog, first-contact resolution. They're all flow and reliability measures, and they share a structure with "},{"type":"wikilink","attrs":{"title":"Support analytics"}},{"type":"text","text":": one row per event, state transitions captured, rates computed off a clean grain."}]},{"type":"paragraph","content":[{"type":"text","text":"The modeling lesson is that an SLO is a measured thing and an SLA is a promise, and conflating them in a report makes you either complacent or panicked. Keep the internal objective and the external commitment as separate measures, both defined once. This is the operational corner of the same "},{"type":"wikilink","attrs":{"title":"Counting & aggregation"}},{"type":"text","text":" discipline used everywhere else."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Throughput, cycle time and capacity"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Support analytics"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Counting & aggregation"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Throughput, cycle time and capacity', 'throughput-cycle-time-capacity', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"These three are classic operations-research ideas applied to a SaaS business: how much work gets done, how long each unit takes, and whether you have the capacity for the load. They show up in support queues, infra, onboarding pipelines, and engineering delivery alike."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cycle time — ","marks":[{"type":"bold"}]},{"type":"text","text":"time to complete one unit of work: one ticket, one deploy, one onboarding. The baseline for planning."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Throughput — ","marks":[{"type":"bold"}]},{"type":"text","text":"units of work per unit time. The capacity and scalability picture."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Capacity utilization — ","marks":[{"type":"bold"}]},{"type":"text","text":"the share of available capacity in use. Drives staffing and infra decisions."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Little's Law ties them together: work in progress equals throughput times cycle time. It's a genuinely useful identity, because it says you can't cut cycle time and grow the backlog without adding capacity, and it makes the tradeoff explicit. For modeling, all three reduce to one row per work item with start and end timestamps, the same "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" pattern as a support ticket or a sales opportunity. Get the timestamps right and throughput, cycle time, and utilization all fall out of the same table."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"SLAs, SLOs and operational KPIs"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Capacity forecasting"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Grain"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Efficiency and productivity', 'efficiency-and-productivity', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The efficiency metrics ask whether the business is getting more output per unit of input, and the headline one is revenue per employee. It's the simplest expression of operational efficiency and the most abused."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Revenue per employee — ","marks":[{"type":"bold"}]},{"type":"text","text":"ARR divided by headcount. A private-SaaS median around $130k, peaking in the mid-stage and far higher for infrastructure companies (directional, 2025 data)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ARR per FTE and gross margin per employee — ","marks":[{"type":"bold"}]},{"type":"text","text":"variants that sharpen the picture by accounting for cost structure."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Support and delivery productivity — ","marks":[{"type":"bold"}]},{"type":"text","text":"tickets per agent, onboardings per CSM, the team-level versions."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The honest caveat: revenue per employee is misleading without a peer set of similar stage and go-to-market motion. A product-led company and a sales-led one at the same number are not equally efficient. The 2025 gains attributed to leaner teams and AI are real but causally murky. For analytics, headcount is a "},{"type":"wikilink","attrs":{"title":"Time in data modeling"}},{"type":"text","text":" problem, because roles and cost centers change, which means a slowly changing dimension if you want the history to be honest."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"SaaS COGS and gross margin"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Time in data modeling"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Capacity forecasting"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('SaaS COGS and gross margin', 'saas-cogs-and-gross-margin', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cost of goods sold for a SaaS business is what it costs to deliver the service, and gross margin is what's left after it. The classic SaaS story is 80% margins; the 2026 story is that AI compute is quietly eroding them."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The three pillars of SaaS COGS"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hosting and infrastructure — ","marks":[{"type":"bold"}]},{"type":"text","text":"compute, storage, bandwidth. The FinOps target, typically 6 to 12% of revenue; above 15% signals architectural debt (directional)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Customer support and success — ","marks":[{"type":"bold"}]},{"type":"text","text":"the human cost of keeping customers running."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Professional services — ","marks":[{"type":"bold"}]},{"type":"text","text":"implementation and onboarding, often lower-margin and dilutive to the blended number."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Median total gross margin sits around 77%, with top-quartile subscription margins above 80%, and AI-native products running several points lower because inference is expensive (all directional). Margin is a valuation driver, so it gets watched closely. The connection to analytics is direct: gross margin is only as trustworthy as the COGS attribution underneath it, which is the whole subject of "},{"type":"wikilink","attrs":{"title":"Cost attribution (showback and chargeback)"}},{"type":"text","text":". You can't manage a margin you can't attribute."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"FinOps and cloud cost"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Cost attribution (showback and chargeback)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Efficiency metrics (Rule of 40, magic number, burn multiple)"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('FinOps and cloud cost', 'finops-and-cloud-cost', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"FinOps is the most rigorous discipline in this section: an operational practice for maximizing the business value of cloud spend, run jointly by engineering, finance, and product. It's standardized by the FinOps Foundation, with a framework, certifications, and the FOCUS billing spec."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The framework in brief"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Three phases — ","marks":[{"type":"bold"}]},{"type":"text","text":"Inform (visibility and allocation), Optimize (rightsizing, commitments, killing waste), Operate (continuous monitoring and governance). A crawl-walk-run loop."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Core principles — ","marks":[{"type":"bold"}]},{"type":"text","text":"everyone owns their usage, decisions are driven by business value, data is timely and accessible, a central team enables the practice."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cloud+ and Scopes — ","marks":[{"type":"bold"}]},{"type":"text","text":"the 2025 framework expanded beyond public cloud to cover SaaS, licensing, data centers, and AI as first-class scopes."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The reason FinOps belongs in an analytics-engineering wiki is that its core capabilities, cost allocation, anomaly detection, unit economics, are modeling problems. The FOCUS spec gives you a standard billing schema to model against, which is a gift, because it means the cost data arrives with a defined grain. The practical work is in "},{"type":"wikilink","attrs":{"title":"Cost attribution (showback and chargeback)"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"FOCUS and cloud billing exports"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"SaaS COGS and gross margin"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Cost attribution (showback and chargeback)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"FOCUS and cloud billing exports"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Cost attribution (showback and chargeback)', 'cost-attribution-showback-chargeback', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cost attribution is the act of assigning every dollar of cloud and tooling spend to the team, product, or customer that drove it. It's the foundational FinOps capability and the one that turns a single scary bill into something you can actually manage."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Allocation — ","marks":[{"type":"bold"}]},{"type":"text","text":"tag-based and rule-based assignment of costs to owners. Shared and untaggable costs need an explicit split rule, which is itself a model."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Showback — ","marks":[{"type":"bold"}]},{"type":"text","text":"surface each team's costs for awareness, while the bill stays on the central budget. The first step, low-stakes, culture-building."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Chargeback — ","marks":[{"type":"bold"}]},{"type":"text","text":"actually move the money to the consuming team's budget. The forcing function, run after showback has fixed the allocation gaps."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The unit-economics payoff is cost per customer, per feature, per tenant, the bridge from the cloud bill to gross margin and pricing. The standard guidance is to run showback for a quarter before chargeback, because chargeback with bad allocation just starts fights. This is a "},{"type":"wikilink","attrs":{"title":"Relationships"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" modeling problem at heart: fan a cost fact out to the business dimensions that own it, including the awkward shared costs."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"FinOps and cloud cost"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Cost as a data product"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Cost attribution models in dbt"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Cost as a data product', 'cost-as-a-data-product', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Here's the idea that ties operations analytics back to taro's design principles: cost and usage data deserve the same rigor as any other data product. Grain, ownership, definitions, tests, and a home in the warehouse where people can actually use it."}]},{"type":"paragraph","content":[{"type":"text","text":"The motivating observation is behavioral: seeing the bill doesn't change anyone's behavior, but knowing you own a modeled, attributed portion of it does. A monthly cloud invoice emailed to a finance inbox changes nothing. A governed cost model that tells a team their service costs $4,000 a month and which query is responsible changes everything."}]},{"type":"paragraph","content":[{"type":"text","text":"The data platform itself is now a major cost center, so the most immediate application is turning FinOps thinking on the warehouse: cost by warehouse, by job, by query, mapped to owners and use cases. That makes "},{"type":"wikilink","attrs":{"title":"Materialization strategies"}},{"type":"text","text":" a cost decision, not just a performance one. Model the cost data with explicit grain and ownership, publish it as a product, and showback and chargeback become trustworthy instead of contentious. This is the same move as "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":", pointed at the bill."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Cost attribution (showback and chargeback)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Materialization strategies"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Ops voices and canon', 'ops-voices-and-canon', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Operations analytics has one rigorous canon (FinOps) and several diffuse ones. Be honest about which is which."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"FinOps, the rigorous one"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The FinOps Foundation — ","marks":[{"type":"bold"}]},{"type":"text","text":"under the Linux Foundation. The framework, the FOCUS spec, certifications, the State of FinOps report, and the FinOps X conference. The authoritative body."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cloud FinOps, Storment and Fuller (O'Reilly) — ","marks":[{"type":"bold"}]},{"type":"text","text":"the canonical book; the second edition (2023) is current. There's no third edition as of 2026."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The diffuse ones"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"BizOps — ","marks":[{"type":"bold"}]},{"type":"text","text":"genuinely lacks a unifying book or voice. The writing is scattered across operator blogs and company engineering posts. Say so."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"RevOps — ","marks":[{"type":"bold"}]},{"type":"text","text":"heavily vendor-led canon (HubSpot, Clari, Gong ecosystems), few neutral authorities. Covered on the sales side."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cost-as-a-data-product — ","marks":[{"type":"bold"}]},{"type":"text","text":"an emerging idea in the dbt and data-platform community, not yet a formal canon."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Every benchmark in this section, revenue per employee, hosting as a share of revenue, gross margin, comes from vendor and advisory blogs citing surveys, not primary data. Directional only. Some 2026 market and acquisition claims are single-source and should be verified before anyone relies on them.","marks":[{"type":"italic"}]}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Operations analytics practice', 'ops-analytics-practice', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The theory is the metrics and the frameworks. This hub is the build: attributing cost, modeling the billing exports, forecasting capacity, and governing operational metrics like any other."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cost attribution models in dbt."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"FOCUS and cloud billing exports, the raw substrate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Capacity forecasting from throughput and headcount."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Operational metrics in the semantic layer, and the hub-and-spoke org debate."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Operations analytics"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Cost as a data product"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Cost attribution models in dbt', 'cost-attribution-models-in-dbt', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cost attribution is the central ops-modeling problem: take raw cost lines and fan them out to the business dimensions that own them. The FOCUS spec gives you a standard source schema; the attribution is your transformation layer."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The build"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stage the billing exports — ","marks":[{"type":"bold"}]},{"type":"text","text":"the cloud cost lines (AWS CUR, GCP and Azure exports), normalized, ideally via FOCUS."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Apply allocation rules — ","marks":[{"type":"bold"}]},{"type":"text","text":"tag-based assignment to team, product, and customer, plus explicit split rules for shared and untaggable costs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build unit-economics marts — ","marks":[{"type":"bold"}]},{"type":"text","text":"cost divided by a denominator dimension, customers or transactions or tenants, for cost-per-X. Define the denominator once to avoid drift."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The hardest part is the shared costs, the load balancer or the data platform that serves everyone, because there's no clean tag and the split rule is a judgment encoded as a model. Make that rule explicit and version it, the same as any contested definition. This is a "},{"type":"wikilink","attrs":{"title":"Relationships"}},{"type":"text","text":" problem (one cost fact, many owning dimensions) and a "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" problem (does the attributed total reconcile to the actual bill). Assert that reconciliation, or the attribution is just a guess with a schema."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Cost attribution (showback and chargeback)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"FOCUS and cloud billing exports"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('FOCUS and cloud billing exports', 'focus-and-cloud-billing-exports', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Underneath every cloud cost tool sits the raw billing export, and that's what you actually model. The big three each emit one: the AWS Cost and Usage Report to S3, the GCP billing export to BigQuery, and Azure Cost Management exports. They're large, detailed, and inconsistent with each other."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"FOCUS"}]},{"type":"paragraph","content":[{"type":"text","text":"FOCUS, the FinOps Open Cost and Usage Specification, is the standard that normalizes these into one schema, and recent versions extend it to SaaS and PaaS billing too. For an analytics engineer this is a real gift: instead of three bespoke parsers, you model against one defined schema with a known grain, one row per resource per time period per cost component."}]},{"type":"paragraph","content":[{"type":"text","text":"The modeling pattern is the familiar one: land the raw export, stage it into the FOCUS shape, then build the attribution and unit-economics models on top. The grain is everything here, because a cost line is the atomic fact for all of operations analytics, and getting it right is what makes "},{"type":"wikilink","attrs":{"title":"Cost attribution models in dbt"}},{"type":"text","text":" possible. This is "},{"type":"wikilink","attrs":{"title":"The forms of data"}},{"type":"text","text":" applied to the bill: a messy, semi-structured export becoming a clean, modeled fact."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Cost attribution models in dbt"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"FinOps and cloud cost"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The forms of data"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Capacity forecasting', 'capacity-forecasting', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Capacity forecasting predicts whether you'll have enough, of infrastructure, of headcount, of support capacity, to meet future load. It's where the throughput and cost models become forward-looking, and it's a planning tool more than a precision instrument."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The inputs"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Throughput and cycle time — ","marks":[{"type":"bold"}]},{"type":"text","text":"the current rate and per-unit time, the base for projecting load."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Headcount and utilization — ","marks":[{"type":"bold"}]},{"type":"text","text":"how much human capacity exists and how much is used, the staffing side."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Commitment coverage — ","marks":[{"type":"bold"}]},{"type":"text","text":"for cloud, how much usage is covered by reserved or committed pricing versus on-demand, the rate-optimization lever."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The honest framing is that capacity forecasting is scenario planning, not prophecy: you model a few demand scenarios and check whether capacity holds, rather than predicting one exact number. Little's Law does the support and infra math; commitment coverage does the cloud-cost math. The modeling foundation is the same throughput and headcount facts from "},{"type":"wikilink","attrs":{"title":"Throughput, cycle time and capacity"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Efficiency and productivity"}},{"type":"text","text":", projected forward with explicit assumptions you can change and re-run."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Throughput, cycle time and capacity"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Efficiency and productivity"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Operational metrics in the semantic layer"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Operational metrics in the semantic layer', 'operational-metrics-in-the-semantic-layer', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Operational metrics suffer the same drift as every other domain: SLA compliance, mean time to recovery, revenue per employee, cost per customer, all defined slightly differently in each team's dashboard. The fix is the same one taro applies everywhere, define them once in the semantic layer."}]},{"type":"paragraph","content":[{"type":"text","text":"This matters more in ops than it looks, because operational metrics are exactly the ones used across organizational boundaries: finance, engineering, and the business all quote cost per customer and all need it to mean the same thing. A governed definition is what lets a hub-and-spoke org actually share numbers instead of arguing about them."}]},{"type":"paragraph","content":[{"type":"text","text":"Define the SLA, the utilization rate, the unit cost once, with their grain and filters baked in, and serve them to BI, to the cost dashboards, and to any agent that reads them. This is "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":" pointed at operations, and it's the connective tissue that makes the "},{"type":"wikilink","attrs":{"title":"Org models (hub and spoke)"}},{"type":"text","text":" model coherent rather than just an org chart."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Org models (hub and spoke)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Cost as a data product"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Org models (hub and spoke)', 'org-models-hub-and-spoke', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Who owns operations analytics, and indeed all of analytics, is a structural question with a recurring answer. The two extremes both fail in predictable ways."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Centralized — ","marks":[{"type":"bold"}]},{"type":"text","text":"one team owns everything. Consistent definitions, but it becomes a ticket queue disconnected from domain context."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Embedded — ","marks":[{"type":"bold"}]},{"type":"text","text":"analysts inside each function. Fast and contextual, but knowledge fragments and metric logic gets duplicated and drifts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hub and spoke — ","marks":[{"type":"bold"}]},{"type":"text","text":"a central platform-and-governance hub publishes shared models and definitions; embedded domain spokes own their domain logic. Balances both."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The current consensus lands on hub and spoke, and the semantic layer is what makes it work: the hub owns the platform and the conformed definitions, the spokes own their domain, and they share numbers because they share definitions. Its stated weakness is funding the central hub when the budgets sit in the business units, which is a real org-politics problem, not a technical one."}]},{"type":"paragraph","content":[{"type":"text","text":"This is the same debate as "},{"type":"wikilink","attrs":{"title":"Team and ownership models"}},{"type":"text","text":" in product analytics, and the same answer: don't treat the org chart as the lever for data culture, invest in shared systems and definitions instead. The structure follows the semantic layer, not the other way around."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Operational metrics in the semantic layer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Team and ownership models"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"RevOps as a function"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
update pages c set parent_id = pa.id from pages pa where pa.slug = 'ops-analytics' and c.slug in ('what-ops-analytics-is','slas-slos-operational-kpis','throughput-cycle-time-capacity','efficiency-and-productivity','saas-cogs-and-gross-margin','finops-and-cloud-cost','cost-attribution-showback-chargeback','cost-as-a-data-product','ops-voices-and-canon','ops-analytics-practice');
update pages c set parent_id = pa.id from pages pa where pa.slug = 'ops-analytics-practice' and c.slug in ('cost-attribution-models-in-dbt','focus-and-cloud-billing-exports','capacity-forecasting','operational-metrics-in-the-semantic-layer','org-models-hub-and-spoke');
